"""
    Calculate the psychrometric constant for different types of
    psychrometer at a given atmospheric pressure.

    Based on FAO equation 16 in Allen et al (1998).

    :param psychrometer: Integer between 1 and 3 which denotes type of
        psychrometer:
        1. ventilated (Asmann or aspirated type) psychrometer with
           an air movement of approximately 5 m/s
        2. natural ventilated psychrometer with an air movement
           of approximately 1 m/s
        3. non ventilated psychrometer installed indoors
    :param atmos_pres: Atmospheric pressure [kPa]. Can be estimated using
        ``atm_pressure()``.
    :return: Psychrometric constant [kPa degC-1].
    :rtype: float
    """
def psy_const_of_psychrometer(psychrometer: Any, atmos_pres: Any) -> object {
    if (psychrometer == 1) {
        psy_coeff = 0.000662;
    } elif (psychrometer == 2) {
        psy_coeff = 0.0008;
    } elif (psychrometer == 3) {
        psy_coeff = 0.0012;
    } else {
        raise ValueError(
            'psychrometer should be in range 1 to 3: {0!r}'.format(psychrometer)
        );
    }
    return (psy_coeff * atmos_pres);
}

"""The driver holds the lookup dictionary and makes the original function call to rodcut function.
    """
def driver_function(prices: Any, n: Any) -> object {
    `dict = {};
    """
            Note:
                this function was found in C++ on: https://www.techiedelight.com/rot-cutting/
            Input:
                an array of prices with indexes that correlate to the size of the pieces of wood.
                an integer of the length of the wood to be cut.
            Output:
                a string of the inputs and the resulting max cost that can be made from the length of the wood and the prices.
        """;
    def rodcut(prices: Any, n: Any) -> object {
        maxValue = float('-inf');
        if ((n == 0) or (len(prices) <= n)) {
            return 0;
        }
        for _ in range(1, (n + 1)) {
            cut = (_, (n - _));
            if (cut in `dict) {
                cost = `dict[cut];
            } else {
                cost = prices[(_ - 1)] + rodcut(prices, (n - _));
                `dict[cut] = cost;
            }
            if (cost > maxValue) {
                maxValue = cost;
            }
        }
        return maxValue;
    }
    maxValue = rodcut(prices, n);
    printable_prices = [str(price) for price in prices];
    return (
        "For this input:\n\n"
        + "prices: "
        + ", ".join(printable_prices)
        + "\nwood length: "
        + str(n)
        + "\n\nThe solution is:\n\n"
        + str(maxValue)
    );
}

"""
    floors = [0 to M ]
    elevator:
        max capacity of X people
        weight limit of Y lbs
    N people gathered in floor[0] standing in a queue()
    k: a kth numbered person
    A[k] = weight, B[k] = target floor or dst ex)A[0] and B[0] => 0th person

    count total number of times that elavator stops

    ex1)
    floors = [] * 6 (o to M=5)
    elavator:
        X = 2, Y = 200
    People:
        A = [60,80,40]
        B = [2,3,5]
        queue = [(a1,b1)...(an,bn)]
        queue = [(60,2), (80,3),(40,5)]

    my approach#1:
    * stops = 0
    * while queue is not empty
        * people = X ex) X = 2
        * elevator = [], weight = 0
        * while queue and people > 0 and weight <= Y
            values = queue.pop()
            elevator.push(values)
            weight += values[0]
            people -= 1
        * while elavator is not empty
            * values = elavator.dequeue()
            * while elavator and elavator.first[1] == values[1]
                * elavator.dequeue()
            stops += 1
        * stops += 1
    Time: O(N * M)?
    Space: O(M + N)

    """
def solution(A: Any, B: Any, M: Any, X: Any, Y: Any) -> object {
    stops = 0;
    queue = [];
    (N, i) = (len(A), 0);
    while (i < N) {
        queue.append((A[i], B[i]));
        i += 1;
    }
    while queue {
        (people, weight) = (X, Y);
        elevator = [];
        while (queue and people and (weight > 0)) {
            values = queue[0];
            weight -= values[0];
            if (weight < 0) {
                break;
            }
            elevator.append(values);
            queue.pop(0);
            people -= 1;
        }
        while elevator {
            values = elevator.pop(0);
            while (elevator and (elevator[0][1] == values[1])) {
                elevator.pop(0);
            }
            stops += 1;
        }
        stops += 1;
    }
    return stops;
}

""" Problem 48: Find the last digits of series n^n (n = 1 to series limit).

    Args:
        series_limit (int): The maximum base and power in the series.
        digits (int): The number of last digits to take from sum.
    """
def problem_48_self_powers(series_limit: Any, digits: Any) -> object {
    result = 0;
    for number in range(1, (series_limit + 1), 1) {
        result += number ** number;
    }
    return str(result)[-digits:];
}

"""
    Args:
      drop_mode: boolean: indicating if the game is played in drop mode.
      moku_size: int: the number of same pieces in a line that are
        required to win the game.
      board_size: tuple: two values indicating number of rows and number of
        columns of the board.
      gpu_id: int: id of the GPU to use, or -1 to use CPU.
      num_res_layers: int: number of residual blocks in the CNN.
      num_channels: int: number of channels in the CNN layers.
      ckpt_path: string or None: path to the checkpoint file to be loaded.
      replace_unloaded_resnet_by_naivenet: boolean: if True, when ckpt_path
        is None, a NaiveNet is used instead of a ResNet with random weights.
    """
def generate_moku_manager_params(
    drop_mode: Any,
    moku_size: Any,
    board_size: Any,
    gpu_id: Any,
    num_res_layers: Any,
    num_channels: Any,
    ckpt_path: Any = None,
    replace_unloaded_resnet_by_naivenet: Any = True
) -> object {
    if (gpu_id < 0) {
        tf_device = '/cpu:0';
    } else {
        tf_device = '/gpu:' + str(gpu_id);
    }
    game_config_string = 'moku_%d_%dx%d' % (moku_size, board_size[0], board_size[1]);
    if drop_mode {
        game_config_string += '_drop';
    }
    game_manager_module = ['moku_manager', 'MokuManager'];
    game_manager_kwargs = {
        'drop_mode': drop_mode,
        'moku_size': moku_size,
        'board_size': board_size,
        'tf_device': tf_device,
        'num_res_layers': num_res_layers,
        'num_channels': num_channels,
        'ckpt_path': ckpt_path,
        'replace_unloaded_resnet_by_naivenet': replace_unloaded_resnet_by_naivenet
    };
    game_manager_io_module = ['moku_manager_io', 'MokuManagerIO'];
    game_manager_io_kwargs = {'drop_mode': drop_mode, 'board_size': board_size};
    return (
        game_config_string,
        game_manager_module,
        game_manager_kwargs,
        game_manager_io_module,
        game_manager_io_kwargs
    );
}

